"""Generated Worker-safe console assets; do not edit by hand."""

FOUNDATION_HTML = '<!doctype html>\n<html lang="en">\n<head>\n  <meta charset="utf-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <meta name="color-scheme" content="light dark">\n  <title>Sessionbuddy Foundation Review</title>\n  <link rel="stylesheet" href="/foundation/assets/console.css">\n  <script src="/foundation/assets/console.js" defer></script>\n</head>\n<body>\n  <a class="skip-link" href="#content">Skip to content</a>\n  <header>\n    <p class="eyebrow">Sessionbuddy · foundation review</p>\n    <h1>Runtime and performance</h1>\n    <p>This surface reports only safe operational metadata. It contains no event, speaker, or submission data.</p>\n    <span class="badge badge-warning">Synthetic / local</span>\n  </header>\n  <main id="content" tabindex="-1">\n    <div id="notice" class="notice" role="status" aria-live="polite">Loading current request evidence…</div>\n    <section aria-labelledby="runtime-title">\n      <h2 id="runtime-title">Runtime status</h2>\n      <dl class="metric-grid">\n        <div><dt>API</dt><dd id="api-state">Checking…</dd></div>\n        <div><dt>Environment</dt><dd id="environment">Unknown</dd></div>\n        <div><dt>Runtime</dt><dd id="runtime">Unknown</dd></div>\n        <div><dt>Request ID</dt><dd id="request-id">Unavailable</dd></div>\n      </dl>\n    </section>\n    <section aria-labelledby="timing-title">\n      <h2 id="timing-title">Current request timing</h2>\n      <p class="context">A single live request, not benchmark history. Units: milliseconds.</p>\n      <dl id="timings" class="metric-grid"><div><dt>Total</dt><dd>Awaiting response</dd></div></dl>\n    </section>\n    <section aria-labelledby="slo-title">\n      <h2 id="slo-title">API performance contracts</h2>\n      <p class="context">Definitions only · no live sample set · p95 budget.</p>\n      <div class="table-scroll"><table>\n        <thead><tr><th scope="col">Route</th><th scope="col">Owner</th><th scope="col">p95</th><th scope="col">Max errors</th><th scope="col">Benchmark</th></tr></thead>\n        <tbody id="slos"><tr><td colspan="5">Loading…</td></tr></tbody>\n      </table></div>\n    </section>\n    <section aria-labelledby="coverage-title">\n      <h2 id="coverage-title">Observability coverage</h2>\n      <p class="context">Missing and planned signals are intentionally distinct from healthy zero values.</p>\n      <ul id="coverage" class="coverage-list"><li>Loading…</li></ul>\n    </section>\n    <section aria-labelledby="progress-title">\n      <h2 id="progress-title">Build progress</h2>\n      <p class="context">What is implemented now and what the next product slice will add.</p>\n      <div class="table-scroll"><table>\n        <thead><tr><th scope="col">Wave</th><th scope="col">Capability</th><th scope="col">State</th><th scope="col">Evidence</th></tr></thead>\n        <tbody id="build-progress"><tr><td colspan="4">Loading…</td></tr></tbody>\n      </table></div>\n    </section>\n    <aside aria-labelledby="debug-title">\n      <h2 id="debug-title">Debug path</h2>\n      <ol>\n        <li>Record environment, route template, request ID, and visible symptom.</li>\n        <li>Split browser, network, Worker, authorization, and database time.</li>\n        <li>Compare equivalent seed, device, concurrency, and cold/warm conditions.</li>\n        <li>Reproduce with synthetic data and add a regression test before fixing.</li>\n      </ol>\n      <p><a href="/api/v1/openapi.json">Inspect the OpenAPI contract</a></p>\n    </aside>\n  </main>\n  <noscript>This console needs JavaScript to fetch current, non-sensitive runtime evidence.</noscript>\n</body>\n</html>\n'

CONSOLE_CSS = ':root { font-family: Inter, ui-sans-serif, system-ui, sans-serif; color: #14211c; background: #f3f6f4; }\n* { box-sizing: border-box; }\nbody { margin: 0; line-height: 1.5; }\nheader, main { width: min(72rem, calc(100% - 2rem)); margin-inline: auto; }\nheader { padding: 3.5rem 0 1.5rem; }\nh1 { max-width: 15ch; margin: .15rem 0 .5rem; font-size: clamp(2rem, 7vw, 4rem); line-height: 1; }\nh2 { margin-top: 0; }\n.eyebrow { text-transform: uppercase; letter-spacing: .12em; font-weight: 700; color: #27624d; }\n.badge { display: inline-block; padding: .3rem .65rem; border-radius: 999px; font-weight: 700; }\n.badge-warning { color: #694400; background: #ffe19a; }\nmain { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1rem; padding-bottom: 4rem; }\nsection, aside, .notice { padding: 1.25rem; border: 1px solid #cbd8d1; border-radius: .8rem; background: #fff; }\n.notice { grid-column: 1 / -1; }\n.notice.error { border-color: #b63131; color: #7f1d1d; }\n.metric-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: .75rem; }\n.metric-grid div { padding: .85rem; background: #edf4f0; border-radius: .5rem; min-width: 0; }\ndt { color: #496157; font-size: .85rem; }\ndd { margin: .15rem 0 0; font-weight: 700; overflow-wrap: anywhere; }\n.context { color: #52645c; }\n.table-scroll { overflow-x: auto; }\ntable { width: 100%; border-collapse: collapse; }\nth, td { padding: .65rem; text-align: left; border-bottom: 1px solid #dce5e0; }\n.coverage-list { padding: 0; list-style: none; }\n.coverage-list li { display: flex; justify-content: space-between; gap: .75rem; padding: .65rem 0; border-bottom: 1px solid #dce5e0; }\n.state-available { color: #17613e; }\n.state-planned { color: #765300; }\n.state-missing { color: #9a2929; }\na { color: #075e48; }\na:focus-visible { outline: 3px solid #e69b00; outline-offset: 3px; }\n.skip-link { position: absolute; left: .5rem; top: -4rem; padding: .5rem; background: #fff; z-index: 1; }\n.skip-link:focus { top: .5rem; }\n@media (max-width: 48rem) { main { grid-template-columns: 1fr; } .metric-grid { grid-template-columns: 1fr; } header { padding-top: 2rem; } }\n@media (prefers-reduced-motion: reduce) { *, *::before, *::after { scroll-behavior: auto !important; } }\n@media (prefers-color-scheme: dark) { :root { color: #edf6f1; background: #101814; } section, aside, .notice { background: #18251f; border-color: #365247; } .metric-grid div { background: #22362d; } .context, dt { color: #b9cec4; } th, td, .coverage-list li { border-color: #365247; } a { color: #7ad7b5; } .state-available { color: #83d9b5; } .state-planned { color: #f2c96d; } .state-missing { color: #ff9696; } }\n'

CONSOLE_JS = '(() => {\n  "use strict";\n  const byId = (id) => document.getElementById(id);\n  const text = (value) => document.createTextNode(String(value));\n  const cell = (tag, value) => { const node = document.createElement(tag); node.append(text(value)); return node; };\n  const vitals = { lcp_ms: null, inp_ms: null, cls: 0, fcp_ms: null };\n\n  function observeVitals() {\n    if (!("PerformanceObserver" in window)) return;\n    const watch = (type, callback) => {\n      try { new PerformanceObserver(callback).observe({ type, buffered: true }); } catch (_) { /* unsupported */ }\n    };\n    watch("largest-contentful-paint", (list) => {\n      const entries = list.getEntries();\n      if (entries.length) vitals.lcp_ms = entries[entries.length - 1].startTime;\n    });\n    watch("event", (list) => {\n      for (const entry of list.getEntries()) vitals.inp_ms = Math.max(vitals.inp_ms || 0, entry.duration);\n    });\n    watch("layout-shift", (list) => {\n      for (const entry of list.getEntries()) if (!entry.hadRecentInput) vitals.cls += entry.value;\n    });\n    watch("paint", (list) => {\n      const fcp = list.getEntries().find((entry) => entry.name === "first-contentful-paint");\n      if (fcp) vitals.fcp_ms = fcp.startTime;\n    });\n  }\n\n  function parseServerTiming(header) {\n    if (!header) return [];\n    return header.split(",").flatMap((part) => {\n      const match = part.trim().match(/^([a-z]+);dur=([0-9.]+)$/);\n      return match ? [{ name: match[1], duration: Number(match[2]) }] : [];\n    });\n  }\n\n  function telemetryDraft(requestId, criticalApiMs) {\n    const navigation = performance.getEntriesByType("navigation")[0];\n    const width = window.innerWidth;\n    return {\n      schema_version: 1,\n      page_template: "/foundation",\n      navigation_type: navigation?.type || "unknown",\n      device_class: width < 640 ? "mobile" : width < 1024 ? "tablet" : "desktop",\n      sampled: false,\n      lcp_ms: vitals.lcp_ms,\n      inp_ms: vitals.inp_ms,\n      cls: vitals.cls,\n      ttfb_ms: navigation ? Math.max(0, navigation.responseStart) : null,\n      fcp_ms: vitals.fcp_ms,\n      critical_api_ms: criticalApiMs,\n      api_request_id: requestId || null\n    };\n  }\n\n  async function load() {\n    const started = performance.now();\n    try {\n      const response = await fetch("/api/v1/foundation/status", { headers: { accept: "application/json" } });\n      if (!response.ok) throw new Error(`Status API returned ${response.status}`);\n      const model = await response.json();\n      const requestId = response.headers.get("x-request-id");\n      const requestMs = Math.max(0, performance.now() - started);\n      byId("api-state").textContent = "Healthy response";\n      byId("environment").textContent = `${model.environment} · ${model.data_classification}`;\n      byId("runtime").textContent = model.runtime;\n      byId("request-id").textContent = requestId || "Unavailable";\n      byId("notice").textContent = "Current API evidence loaded. Historical charts are not connected yet.";\n\n      const timings = parseServerTiming(response.headers.get("server-timing"));\n      const timingList = byId("timings"); timingList.replaceChildren();\n      (timings.length ? timings : [{ name: "round trip", duration: requestMs }]).forEach((item) => {\n        const wrap = document.createElement("div");\n        wrap.append(cell("dt", item.name), cell("dd", `${item.duration.toFixed(1)} ms`));\n        timingList.append(wrap);\n      });\n\n      const sloBody = byId("slos"); sloBody.replaceChildren();\n      model.slos.forEach((slo) => {\n        const row = document.createElement("tr");\n        [slo.route, slo.owner, `${slo.p95_ms} ms`, `${(slo.error_rate_max * 100).toFixed(2)}%`, slo.benchmark]\n          .forEach((value) => row.append(cell("td", value)));\n        sloBody.append(row);\n      });\n\n      const coverage = byId("coverage"); coverage.replaceChildren();\n      model.coverage.forEach((item) => {\n        const row = document.createElement("li");\n        row.append(cell("span", `${item.signal} · ${item.source}`));\n        const state = cell("strong", item.state); state.className = `state-${item.state}`;\n        row.append(state); coverage.append(row);\n      });\n\n      const progress = byId("build-progress"); progress.replaceChildren();\n      model.build_progress.forEach((item) => {\n        const row = document.createElement("tr");\n        [item.wave, item.capability, item.state.replace("_", " "), item.evidence]\n          .forEach((value) => row.append(cell("td", value)));\n        progress.append(row);\n      });\n\n      // Privacy-safe payload is intentionally not transmitted until an audited,\n      // rate-limited ingestion endpoint exists. It is available to integration tests.\n      window.__sessionbuddyTelemetryDraft = telemetryDraft(requestId, requestMs);\n    } catch (error) {\n      byId("api-state").textContent = "Unavailable";\n      byId("notice").textContent = `Telemetry missing: ${error.message}`;\n      byId("notice").classList.add("error");\n    }\n  }\n  observeVitals();\n  load();\n})();\n'

ASSETS = {'foundation.html': 'FOUNDATION_HTML', 'console.css': 'CONSOLE_CSS', 'console.js': 'CONSOLE_JS'}
